:root {
  color: #172033;
  background: #f4f6fa;
  font: 16px/1.5 system-ui, sans-serif;
}

body {
  margin: 0;
}

.container {
  width: min(100% - 2rem, 46rem);
  margin: 3rem auto;
  padding: 2rem;
  background: white;
  border: 1px solid #dce2eb;
  border-radius: 0.75rem;
  box-shadow: 0 0.5rem 1.5rem #1720330d;
